(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.12)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11 + Math.cos((x-y)*0.01-t*0.15)*7;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*6 + Math.cos(sy*0.02-t*0.35)*5;
  const w2y = Math.cos(sy*0.022-t*0.38)*7 + Math.sin(sx*0.018+t*0.42)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [60+Math.sin(t*0.45+3)*70,120+Math.cos(t*0.65+2)*80,0.11,2.1,0.9],
    [400+Math.cos(t*0.55+1)*60,180+Math.sin(t*0.75+4)*50,0.05,2.4,1.1]
  ];
  let aS=0,iS=0,harm=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    harm+=Math.sin(d*f*1.4-t*sp*0.8+0.7)*amp*0.3;
  }
  const n=src.length,act=aS/n,inh=iS/n,har=harm/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1)+Math.sin(fx*0.05+fy*0.05-t*0.6))/3+Math.sin((fx+fy)*0.12+t*2.5)*0.15+Math.sin((fx-fy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.8)*0.5)*0.3;
