  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5+Math.sin(fx*0.08-fy*0.12+t*0.6)*0.3)*1.5)*0.25;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*1.5:1.0;
  const blend=reaction*0.7+cell*0.2+caustic*0.1,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,80],[15,85,115],[20,140,130],[60,170,120],[180,190,60],[220,170,50],[210,110,55],[180,60,70],[120,30,60],[60,15,55],[20,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*f,g=pal[i][1]+(pal[i+1][1]-pal[i][1])*f,b=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const breath=0.9+Math.sin(t*0.5)*0.05+Math.sin(t*0.3+1)*0.05;
